package com.bank.elevator;

import java.util.*;
import java.util.logging.Logger;

enum Direction { UP, DOWN, IDLE }

class Request {
    final int floor; final Direction dir;
    Request(int floor, Direction dir) { this.floor = floor; this.dir = dir; }
}

class Elevator {
    private static final Logger log = Logger.getLogger("ELEV");
    final String id; int currentFloor = 0; Direction direction = Direction.IDLE;
    final int maxWeightKg; int loadKg = 0;
    final TreeSet<Integer> upStops = new TreeSet<>();
    final TreeSet<Integer> downStops = new TreeSet<>(Comparator.reverseOrder());
    Elevator(String id, int maxWeightKg) { this.id = id; this.maxWeightKg = maxWeightKg; }

    void addStop(int floor) {
        if (floor >= currentFloor) upStops.add(floor); else downStops.add(floor);
        if (direction == Direction.IDLE) direction = floor >= currentFloor ? Direction.UP : Direction.DOWN;
    }
    boolean canBoard(int extraKg) { return loadKg + extraKg <= maxWeightKg; }

    void step() { // SCAN/LOOK: serve current direction fully, then reverse
        if (direction == Direction.UP && !upStops.isEmpty()) {
            currentFloor = upStops.pollFirst(); openDoors();
            if (upStops.isEmpty()) direction = downStops.isEmpty() ? Direction.IDLE : Direction.DOWN;
        } else if (direction == Direction.DOWN && !downStops.isEmpty()) {
            currentFloor = downStops.pollFirst(); openDoors();
            if (downStops.isEmpty()) direction = upStops.isEmpty() ? Direction.IDLE : Direction.UP;
        }
    }
    private void openDoors() { log.info(() -> id + " doors open at floor " + currentFloor); }
}

class ElevatorController {
    private final List<Elevator> cars;
    ElevatorController(List<Elevator> cars) { this.cars = cars; }
    Elevator dispatch(Request r) { // nearest-car scoring
        Elevator best = null; int bestScore = Integer.MAX_VALUE;
        for (Elevator c : cars) {
            int score = Math.abs(c.currentFloor - r.floor);
            if (c.direction != Direction.IDLE && c.direction != r.dir) score += 100;
            if (score < bestScore) { bestScore = score; best = c; }
        }
        best.addStop(r.floor);
        return best;
    }
}

public class ElevatorDemo {
    public static void main(String[] args) {
        Elevator c1 = new Elevator("CAR-1", 680);
        Elevator c2 = new Elevator("CAR-2", 680);
        ElevatorController controller = new ElevatorController(List.of(c1, c2));
        controller.dispatch(new Request(2, Direction.UP));   // Rajesh
        controller.dispatch(new Request(8, Direction.UP));   // Priya going up
        c1.step(); c1.step();
    }
}
