package com.bank.chess;

import java.util.logging.Logger;

enum Color { WHITE, BLACK }

class Cell {
    final int row, col;
    Cell(int row, int col) { this.row = row; this.col = col; }
}

abstract class Piece {
    final Color color;
    Piece(Color color) { this.color = color; }
    abstract boolean canMove(Board b, Cell from, Cell to); // polymorphic rule
}

class Rook extends Piece {
    Rook(Color c) { super(c); }
    boolean canMove(Board b, Cell from, Cell to) {
        if (from.row != to.row && from.col != to.col) return false; // straight only
        return b.pathClear(from, to);
    }
}

class King extends Piece {
    King(Color c) { super(c); }
    boolean canMove(Board b, Cell from, Cell to) {
        return Math.abs(from.row - to.row) <= 1 && Math.abs(from.col - to.col) <= 1;
    }
}

class Board {
    final Piece[][] grid = new Piece[8][8];
    void place(Piece p, Cell c) { grid[c.row][c.col] = p; }
    Piece at(Cell c) { return grid[c.row][c.col]; }
    boolean pathClear(Cell from, Cell to) {
        int dr = Integer.signum(to.row - from.row), dc = Integer.signum(to.col - from.col);
        int r = from.row + dr, c = from.col + dc;
        while (r != to.row || c != to.col) { if (grid[r][c] != null) return false; r += dr; c += dc; }
        return true;
    }
}

class Game {
    private static final Logger log = Logger.getLogger("CHESS");
    private final Board board; private Color turn = Color.WHITE;
    Game(Board board) { this.board = board; }
    boolean makeMove(Cell from, Cell to) {
        Piece p = board.at(from);
        if (p == null || p.color != turn) { log.warning("Not your piece"); return false; }
        if (!p.canMove(board, from, to)) { log.warning("Illegal move"); return false; }
        board.place(p, to); board.grid[from.row][from.col] = null;
        log.info(() -> turn + " moved to (" + to.row + "," + to.col + ")");
        turn = (turn == Color.WHITE) ? Color.BLACK : Color.WHITE; // turn management
        return true;
    }
}

public class ChessDemo {
    public static void main(String[] args) {
        Board board = new Board();
        board.place(new Rook(Color.WHITE), new Cell(0, 0)); // Rajesh (white)
        board.place(new King(Color.BLACK), new Cell(7, 4));  // Priya (black)
        Game game = new Game(board);
        game.makeMove(new Cell(0, 0), new Cell(0, 5)); // legal rook slide
    }
}
