package com.bank.hotel;

import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.logging.Logger;

enum RoomType { STANDARD, DELUXE, SUITE }

class Room {
    final String id; final RoomType type; final BigDecimal nightlyPrice;
    final List<Reservation> reservations = new ArrayList<>();
    Room(String id, RoomType type, BigDecimal price) { this.id = id; this.type = type; this.nightlyPrice = price; }
    boolean isAvailable(LocalDate in, LocalDate out) {
        for (Reservation r : reservations)
            if (r.status != Status.CANCELLED && in.isBefore(r.checkOut) && r.checkIn.isBefore(out)) return false;
        return true;
    }
}

enum Status { CONFIRMED, CHECKED_IN, COMPLETED, CANCELLED }

class Reservation {
    final String id; final Room room; final String guest;
    final LocalDate checkIn, checkOut; Status status = Status.CONFIRMED;
    Reservation(String id, Room room, String guest, LocalDate in, LocalDate out) {
        this.id = id; this.room = room; this.guest = guest; this.checkIn = in; this.checkOut = out;
    }
}

interface CancellationPolicy { BigDecimal penalty(Reservation r, LocalDateTime now); }
class StandardCancellation implements CancellationPolicy {
    public BigDecimal penalty(Reservation r, LocalDateTime now) {
        long hours = Duration.between(now, r.checkIn.atStartOfDay()).toHours();
        if (hours >= 24) return BigDecimal.ZERO;
        long nights = r.checkOut.toEpochDay() - r.checkIn.toEpochDay();
        return r.room.nightlyPrice.multiply(BigDecimal.valueOf(nights)).multiply(new BigDecimal("0.5"));
    }
}

class HotelService {
    private static final Logger log = Logger.getLogger("HOTEL");
    private final CancellationPolicy policy; private int counter = 0;
    HotelService(CancellationPolicy policy) { this.policy = policy; }

    synchronized Reservation book(Room room, String guest, LocalDate in, LocalDate out) {
        if (!room.isAvailable(in, out)) throw new IllegalStateException("Room not available");
        Reservation r = new Reservation("RES-" + (++counter), room, guest, in, out);
        room.reservations.add(r);
        log.info(() -> guest + " booked " + room.id + " " + in + " to " + out);
        return r;
    }
    BigDecimal cancel(Reservation r, LocalDateTime now) {
        r.status = Status.CANCELLED;
        BigDecimal penalty = policy.penalty(r, now);
        log.info(() -> "Cancelled " + r.id + " penalty=" + penalty);
        return penalty;
    }
}

public class HotelDemo {
    public static void main(String[] args) {
        Room deluxe = new Room("D-101", RoomType.DELUXE, new BigDecimal("6000"));
        HotelService svc = new HotelService(new StandardCancellation());
        Reservation r = svc.book(deluxe, "Rajesh", LocalDate.of(2026, 11, 1), LocalDate.of(2026, 11, 5));
        svc.cancel(r, LocalDateTime.of(2026, 10, 31, 12, 0)); // ~12h before → penalty
    }
}
