package com.bank.movie;

import java.util.*;
import java.util.concurrent.locks.ReentrantLock;
import java.util.logging.Logger;

enum SeatStatus { AVAILABLE, LOCKED, BOOKED }

class Show {
    private static final Logger log = Logger.getLogger("MOVIE");
    final String id, movie; final Map<String, SeatStatus> seats = new HashMap<>();
    final Map<String, String> lockedBy = new HashMap<>();
    private final ReentrantLock lock = new ReentrantLock();
    Show(String id, String movie, List<String> seatList) {
        this.id = id; this.movie = movie;
        seatList.forEach(s -> seats.put(s, SeatStatus.AVAILABLE));
    }
    boolean lockSeats(List<String> wanted, String user) {
        lock.lock(); // atomic check-and-set across requested seats
        try {
            for (String s : wanted) if (seats.get(s) != SeatStatus.AVAILABLE) return false;
            for (String s : wanted) { seats.put(s, SeatStatus.LOCKED); lockedBy.put(s, user); }
            log.info(() -> user + " locked " + wanted);
            return true;
        } finally { lock.unlock(); }
    }
    boolean confirm(List<String> wanted, String user) {
        lock.lock();
        try {
            for (String s : wanted) if (!user.equals(lockedBy.get(s))) return false;
            for (String s : wanted) { seats.put(s, SeatStatus.BOOKED); }
            log.info(() -> user + " booked " + wanted);
            return true;
        } finally { lock.unlock(); }
    }
}

class BookingService {
    Show newShow(String id, String movie, List<String> seats) { return new Show(id, movie, seats); }
}

public class MovieDemo {
    public static void main(String[] args) {
        BookingService svc = new BookingService();
        Show show = svc.newShow("SHOW-9PM", "Avengers", List.of("A5", "A6", "A7"));
        boolean rajesh = show.lockSeats(List.of("A5"), "Rajesh");   // wins
        boolean priya  = show.lockSeats(List.of("A5"), "Priya");    // fails, already locked
        Logger.getLogger("MOVIE").info("Rajesh locked=" + rajesh + " Priya locked=" + priya);
        if (rajesh) show.confirm(List.of("A5"), "Rajesh");
    }
}
