    Card(String number, Account account, String pin) { this.number = number; this.account = account; this.pin = pin; }
    boolean checkPin(String entered) { return pin.equals(entered); }
}

class CashDispenser {
    boolean dispense(BigDecimal amount) {
        // real ATM uses denomination breakdown; here assume multiples of 100 work
        return amount.remainder(new BigDecimal("100")).signum() == 0;
    }
}

enum AtmState { IDLE, AUTHENTICATED }

class ATM {
    private static final Logger log = Logger.getLogger("ATM");
    private final CashDispenser dispenser; private final BigDecimal dailyLimit = new BigDecimal("25000");
    private AtmState state = AtmState.IDLE; private Card card;
    ATM(CashDispenser dispenser) { this.dispenser = dispenser; }

    boolean authenticate(Card card, String pin) {
        if (!card.checkPin(pin)) { log.warning("PIN invalid"); return false; }
        this.card = card; state = AtmState.AUTHENTICATED;
        log.info("Authenticated " + card.number);
        return true;
    }
    void withdraw(BigDecimal amount) {
        if (state != AtmState.AUTHENTICATED) throw new IllegalStateException("Authenticate first");
        Account acc = card.account;
        if (acc.balance.compareTo(amount) < 0) { log.severe("Insufficient funds"); return; }
        if (acc.dailyWithdrawn.add(amount).compareTo(dailyLimit) > 0) { log.severe("Daily limit exceeded"); return; }
        acc.debit(amount);                      // debit first
        if (!dispenser.dispense(amount)) {      // then dispense
            acc.credit(amount);                 // reverse if dispense fails (atomicity)
            log.severe("Dispense failed, debit reversed");
            return;
        }
        log.info(() -> "Dispensed " + amount + ", balance=" + acc.balance);
    }
}

public class AtmDemo {
    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));
        Card card = new Card("4111-RAJESH", rajesh, "1234");
        ATM atm = new ATM(new CashDispenser());
        if (atm.authenticate(card, "1234")) atm.withdraw(new BigDecimal("5000"));
    }
}
