package com.bank.logging;

import java.time.LocalDateTime;
import java.util.*;
import java.util.function.Supplier;

enum LogLevel { DEBUG, INFO, WARN, ERROR }

class Formatter {
    String format(LogLevel level, String name, String msg) {
        return LocalDateTime.now() + " [" + level + "] " + name + " - " + msg;
    }
}

interface Appender { void append(String line); }

class ConsoleAppender implements Appender {
    public synchronized void append(String line) { System.out.println(line); } // thread safe
}

class FileAppender implements Appender {
    private final StringBuilder buffer = new StringBuilder(); // simulates a file
    public synchronized void append(String line) { buffer.append(line).append('\n'); }
    String contents() { return buffer.toString(); }
}

class Logger {
    private final String name; private final LogLevel threshold;
    private final Formatter formatter; private final List<Appender> appenders;
    Logger(String name, LogLevel threshold, Formatter f, List<Appender> appenders) {
        this.name = name; this.threshold = threshold; this.formatter = f; this.appenders = appenders;
    }
    private void log(LogLevel level, Supplier<String> msg) {
        if (level.ordinal() < threshold.ordinal()) return;      // cheap filter
        String line = formatter.format(level, name, msg.get()); // build only if enabled
        for (Appender a : appenders) a.append(line);            // fan out
    }
    void debug(Supplier<String> m) { log(LogLevel.DEBUG, m); }
    void info(Supplier<String> m)  { log(LogLevel.INFO, m); }
    void error(Supplier<String> m) { log(LogLevel.ERROR, m); }
}

class LoggerFactory {
    private static final Map<String, Logger> CACHE = new HashMap<>(); // Singleton-per-name
    static synchronized Logger get(String name, LogLevel level, List<Appender> appenders) {
        return CACHE.computeIfAbsent(name, n -> new Logger(n, level, new Formatter(), appenders));
    }
}

public class LoggingDemo {
