interface PriceObserver { void onPriceChange(String symbol, BigDecimal price); } // observer

class Stock {                                        // subject
    private static final Logger log = Logger.getLogger("STOCK");
    private final String symbol; private BigDecimal price;
    private final List<PriceObserver> observers = new ArrayList<>();
    Stock(String symbol, BigDecimal price) { this.symbol = symbol; this.price = price; }
    void subscribe(PriceObserver o) { observers.add(o); }
    void unsubscribe(PriceObserver o) { observers.remove(o); }
    void setPrice(BigDecimal newPrice) {
        this.price = newPrice;
        log.info(() -> symbol + " price now " + newPrice);
        for (PriceObserver o : observers) {
            try { o.onPriceChange(symbol, newPrice); }   // one failure must not block others
            catch (Exception e) { log.severe("Observer failed: " + e.getMessage()); }
        }
    }
}

class SmsObserver implements PriceObserver {
    private final String who;
    SmsObserver(String who) { this.who = who; }
    public void onPriceChange(String symbol, BigDecimal price) {
        Logger.getLogger("SMS").info("SMS to " + who + ": " + symbol + " at " + price);
    }
}
