package com.bank.command;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

class Account {
    final String id; BigDecimal balance;
    Account(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

interface Command { void execute(); void undo(); }   // action as object

class TransferCommand implements Command {
    private static final Logger log = Logger.getLogger("CMD");
    private final Account from, to; private final BigDecimal amount;  // captured state
    TransferCommand(Account from, Account to, BigDecimal amount) { this.from = from; this.to = to; this.amount = amount; }
    public void execute() { from.debit(amount); to.credit(amount); log.info(() -> "Transfer " + amount); }
    public void undo()    { to.debit(amount); from.credit(amount); log.info(() -> "Undo transfer " + amount); }
}

class Invoker {
    private final Deque<Command> history = new ArrayDeque<>();
    void execute(Command c) { c.execute(); history.push(c); }  // run + remember
    void undo() { if (!history.isEmpty()) history.pop().undo(); }
}

public class CommandDemo {
    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", new BigDecimal("250000"));
        Invoker invoker = new Invoker();
        invoker.execute(new TransferCommand(rajesh, priya, new BigDecimal("50000")));
        Logger.getLogger("CMD").info("After transfer: Rajesh=" + rajesh.balance + " Priya=" + priya.balance);
        invoker.undo(); // mistake caught → reverse exactly
        Logger.getLogger("CMD").info("After undo: Rajesh=" + rajesh.balance + " Priya=" + priya.balance);
    }
}
