package com.bank.chain;

import java.math.BigDecimal;
import java.util.logging.Logger;

class TransferRequest {
    final String account; final BigDecimal amount; final boolean kycDone; final BigDecimal todayTotal;
    TransferRequest(String account, BigDecimal amount, boolean kycDone, BigDecimal todayTotal) {
        this.account = account; this.amount = amount; this.kycDone = kycDone; this.todayTotal = todayTotal;
    }
}

abstract class Validator {
    private static final Logger log = Logger.getLogger("CHAIN");
    private final Validator next;                       // link to next handler
    Validator(Validator next) { this.next = next; }
    final boolean validate(TransferRequest r) {
        if (!check(r)) { log.severe(getClass().getSimpleName() + " failed"); return false; }
        log.info(getClass().getSimpleName() + " passed");
        return next == null || next.validate(r);        // pass along the chain
    }
    protected abstract boolean check(TransferRequest r);
}

class AmountValidator extends Validator {
    AmountValidator(Validator next) { super(next); }
    protected boolean check(TransferRequest r) { return r.amount.signum() > 0; }
}
class KycValidator extends Validator {
    KycValidator(Validator next) { super(next); }
    protected boolean check(TransferRequest r) { return r.kycDone; }
}
class LimitValidator extends Validator {
    LimitValidator(Validator next) { super(next); }
    protected boolean check(TransferRequest r) {
        return r.todayTotal.add(r.amount).compareTo(new BigDecimal("200000")) <= 0;
    }
}

